            Call("Backend.GuestPassList","UnregisterRoot",owner);var spotRestored=SpotFrame(true,0);Check(spotRestored.S.SequenceEqual(spotStock.S),"depth unregister invalidates and restores exact stock conditional spot bits");SpotFrame(false,0);Check(spotOwners.All(id=>backend.GetPostprocessGeneration(id).Retired==0),"conditional spot owner bundles retire after completion");
            Check(backend.GetStats().ValidationEnabled!=0&&backend.GetStats().ValidationErrors==0,"extended geometry owners have zero core/synchronization errors");
        }finally{Call("Backend.GuestPassList","UnregisterRoot",owner);backend.SetSpots(512,Array.Empty<NativeSpot>());backend.SetLights(Array.Empty<NativeLight>());backend.SetShadowPassConstants(null);backend.ClearPassFrame();stages.GetField("catalog",stat).SetValue(null,null);stages.GetField("catalogEpoch",stat).SetValue(null,-1L);}
        return checks;
    }
}
